<section class="single-herbs-guide__section" aria-labelledby="topic-four-comparisons-title"><h4 id="topic-four-comparisons-title"><?php echo s($bloodtext('High-yield comparisons', 'Comparaciones de alto rendimiento')); ?></h4><p class="single-herbs-guide__section-lead"><?php echo s($bloodtext('Use the decisive clue before opening the full comparison.', 'Usa la pista decisiva antes de abrir la comparación completa.')); ?></p><div class="single-herbs-guide__comparisons"><?php foreach ($bloodcomparisons as $comparison): ?><?php $comparisonpath = $ises && !empty($comparison['path_es']) ? $comparison['path_es'] : $comparison['path']; $comparisonurl = new moodle_url($comparisonpath, ['from' => 'single-herbs', 'focus' => (string) $selected['number']]); ?><a class="single-herbs-guide__comparison" href="<?php echo $comparisonurl->out(false); ?>"><strong><?php echo s($comparison['title']); ?></strong><span><?php echo s($comparison['summary']); ?></span><small><?php echo s($bloodtext('Open full comparison →', 'Abrir comparación completa →')); ?></small></a><?php endforeach; ?></div></section>

